<section class="ms-swproc">

    <style>
        .ms-swproc,
        .ms-swproc * {
            box-sizing: border-box;
        }

        .ms-swproc {
            --purple: #5A2EA6;
            width: 100%;
            padding: 60px 20px 70px;
            background: #fff;
            font-family: var(--font-body);
        }

        .ms-swproc-wrap {
            max-width: 1110px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: repeat(3, minmax(0, 1fr));
            gap: 24px;
        }

        .ms-swproc-card {
            padding: 34px 30px 36px;
            border-radius: 24px;
            border: 1px solid #ececec;
            background: #f6f6f6;
            text-align: center;
            transition: .3s ease;
        }

        .ms-swproc-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 12px 28px rgba(90, 46, 166, .16);
        }

        .ms-swproc-icon {
            width: 62px;
            height: 62px;
            margin: 0 auto 18px;
            border-radius: 50%;
            border: 1px solid #111;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .ms-swproc-icon svg {
            width: 28px;
            height: 28px;
            fill: #111;
        }

        .ms-swproc-card h3 {
            margin: 0 0 14px;
            font-size: 20px;
            line-height: 1.35;
            font-weight: 600;
            color: #000;
        }

        .ms-swproc-card p {
            margin: 0;
            font-size: 14px;
            line-height: 1.8;
            font-weight: 400;
            color: #222;
        }

        /* ---------- Tablet ---------- */
        @media (max-width: 991px) {
            .ms-swproc-wrap {
                grid-template-columns: repeat(2, minmax(0, 1fr));
                gap: 20px;
            }
        }

        /* ---------- Mobile ---------- */
        @media (max-width: 575px) {
            .ms-swproc {
                padding: 35px 14px 45px;
            }

            .ms-swproc-wrap {
                grid-template-columns: 1fr;
                gap: 16px;
            }

            .ms-swproc-card {
                padding: 28px 22px 30px;
            }

            .ms-swproc-card h3 {
                font-size: 18px;
            }
        }
    </style>

    <div class="ms-swproc-wrap">
        <?php foreach ($cards as $card) : ?>
            <div class="ms-swproc-card">
                <div class="ms-swproc-icon"><?php echo $card[0]; ?></div>
                <h3><?php echo htmlspecialchars($card[1]); ?></h3>
                <p><?php echo htmlspecialchars($card[2]); ?></p>
            </div>
        <?php endforeach; ?>
    </div>
</section>